//! R15 differential: the pure Yahoo normalization mappings must match the legacy module.
//!
//! The fixture is generated by running `yfinance_normalize.py` on plain indexed row records;
//! trees are compared exactly (floats 1e-12) and errors byte for byte.

use serde_json::Value;

use sd_providers::yfinance_normalize::{
    normalize_financials, normalize_history, normalize_history_batch, normalize_options,
    repair_diff,
};

fn fixture() -> Value {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../tests/fixtures/yahoo/normalize_cases.json");
    serde_json::from_str(&std::fs::read_to_string(&path).expect("fixture")).expect("json")
}

fn close(left: &Value, right: &Value) -> bool {
    match (left, right) {
        (Value::Number(left), Value::Number(right)) => match (left.as_f64(), right.as_f64()) {
            (Some(left), Some(right)) => {
                (left - right).abs() <= 1e-12 * left.abs().max(right.abs()).max(1.0)
            }
            _ => left == right,
        },
        (Value::Array(left), Value::Array(right)) => {
            left.len() == right.len() && left.iter().zip(right).all(|(l, r)| close(l, r))
        }
        (Value::Object(left), Value::Object(right)) => {
            left.len() == right.len()
                && left.iter().all(|(key, value)| {
                    right
                        .get(key)
                        .map(|other| close(value, other))
                        .unwrap_or(false)
                })
        }
        _ => left == right,
    }
}

fn object(map: Option<&Value>) -> serde_json::Map<String, Value> {
    map.and_then(Value::as_object).cloned().unwrap_or_default()
}

fn run_case(case: &Value) -> Result<Value, (String, String)> {
    let kind = case["kind"].as_str().unwrap_or_default();
    let input = &case["input"];
    match kind {
        "history" => normalize_history(
            &input["frame"],
            &input["metadata"],
            input["price_basis"].as_str().unwrap_or("provider"),
            input["symbol"].as_str(),
            input["interval"].as_str().unwrap_or("1d"),
        )
        .map_err(|message| ("ValueError".to_string(), message)),
        "batch" => {
            let frames = object(input.get("frames"));
            let metadata = object(input.get("metadata"));
            let source_indices = input
                .get("source_indices")
                .and_then(Value::as_object)
                .cloned();
            normalize_history_batch(
                &frames,
                &metadata,
                input["price_basis"].as_str().unwrap_or("provider"),
                input["interval"].as_str().unwrap_or("1d"),
                source_indices.as_ref(),
            )
            .map_err(|message| ("ValueError".to_string(), message))
        }
        "repair" => Ok(repair_diff(
            &input["original"],
            &input["repaired"],
            &input["original_metadata"],
            &input["repaired_metadata"],
        )),
        "options" => Ok(normalize_options(
            &input["chain"],
            input.get("expiration"),
            input.get("underlying"),
        )),
        "financials" => {
            let statements = object(input.get("statements"));
            normalize_financials(
                &statements,
                input["frequency"].as_str().unwrap_or("annual"),
                input.get("currency"),
            )
            .map_err(|message| ("ValueError".to_string(), message))
        }
        other => panic!("unknown case kind {other}"),
    }
}

#[test]
fn yahoo_normalization_matches_legacy() {
    let fixture = fixture();
    let cases = fixture["cases"].as_array().expect("cases");
    assert!(cases.len() >= 20, "expected the normalization corpus");
    for (index, case) in cases.iter().enumerate() {
        let outcome = run_case(case);
        if case["ok"].as_bool() == Some(true) {
            let actual = outcome.unwrap_or_else(|error| {
                panic!(
                    "case {index} {}: unexpected error {:?}",
                    case["kind"], error
                )
            });
            assert!(
                close(&actual, &case["data"]),
                "case {index} {} mismatch\nexpected: {}\nactual: {}",
                case["kind"],
                case["data"],
                actual
            );
        } else {
            let (error_type, message) =
                outcome.expect_err(&format!("case {index} {}: expected failure", case["kind"]));
            assert_eq!(error_type, case["error_type"].as_str().unwrap_or_default());
            assert_eq!(message, case["error_message"].as_str().unwrap_or_default());
        }
    }
}
